const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;

return shortlist.map((candidate) => ({
  json: {
    ...item,
    researchCandidateName: candidate.name
  }
}));

const items = $input.all();
if (items.length === 0) {
  return [{ json: { research: [] } }];
}

const contextItem = items.find((it) => it.json && it.json.playerSearch) || items[0];
const context = { ...(contextItem ? contextItem.json : {}) };
delete context.researchCandidateName;
delete context.researchResult;
delete context.error;

const research = items.map((it) => {
  const j = it.json || {};
  if (j.researchResult) {
    return { ...j.researchResult, uncertain: false, uncertaintyReason: null };
  }

  const candidateName = j.researchCandidateName
    || (j.rankingCandidate && j.rankingCandidate.name)
    || (j.error && j.error.researchCandidateName)
    || 'unbekannter Kandidat';
  const reason = (j.error && (j.error.message || j.error)) || 'Der Research-Zweig fuer diesen Kandidaten ist fehlgeschlagen.';

  return {
    candidate: candidateName,
    club: null,
    contract: null,
    marketValue: null,
    injuries: null,
    news: [],
    source: 'Recherche fehlgeschlagen (keine Quelle verfuegbar)',
    timestamp: new Date().toISOString(),
    confidence: 0,
    uncertain: true,
    uncertaintyReason: String(reason)
  };
});

return [{ json: { ...context, research } }];

const item = $input.item.json;
const research = item.research;
const shortlistNames = (item.playerSearch && Array.isArray(item.playerSearch.shortlist)) ? item.playerSearch.shortlist.map((c) => c.name) : [];
const errors = [];

if (!Array.isArray(research) || research.length === 0) {
  errors.push('research fehlt oder ist leer.');
} else {
  const researchedNames = research.map((r) => r.candidate).filter(Boolean);
  const uniqueResearchedNames = new Set(researchedNames);
  const shortlistSet = new Set(shortlistNames);

  if (researchedNames.length !== uniqueResearchedNames.size) errors.push('research enthaelt denselben Kandidaten mehrfach.');
  const missing = shortlistNames.filter((name) => !uniqueResearchedNames.has(name));
  if (missing.length > 0) errors.push(`research deckt folgende Shortlist-Kandidaten nicht ab: ${missing.join(', ')}.`);
  const unexpected = [...uniqueResearchedNames].filter((name) => !shortlistSet.has(name));
  if (unexpected.length > 0) errors.push(`research enthaelt Kandidaten ausserhalb der Shortlist: ${unexpected.join(', ')}.`);

  research.forEach((r, idx) => {
    if (!r.candidate || !shortlistSet.has(r.candidate)) errors.push(`research[${idx}].candidate fehlt oder ist nicht Teil der Shortlist.`);
    if (typeof r.confidence !== 'number') errors.push(`research[${idx}].confidence fehlt oder ist keine Zahl.`);
    if (!r.source) errors.push(`research[${idx}].source fehlt.`);
    if (!r.timestamp) errors.push(`research[${idx}].timestamp fehlt.`);
    if (!Array.isArray(r.news)) errors.push(`research[${idx}].news ist kein Array.`);
    if (!r.uncertain) {
      if (!r.club) errors.push(`research[${idx}].club fehlt.`);
      if (!r.contract) errors.push(`research[${idx}].contract fehlt.`);
      if (!r.marketValue) errors.push(`research[${idx}].marketValue fehlt.`);
      if (!r.injuries) errors.push(`research[${idx}].injuries fehlt.`);
      if (Array.isArray(r.news) && r.news.length === 0) errors.push(`research[${idx}].news ist leer.`);
    }
  });

  if (research.every((r) => r.uncertain)) errors.push('Fuer keinen Kandidaten konnte eine Recherche erfolgreich durchgefuehrt werden.');
}

const valid = errors.length === 0;
return [{ json: { ...item, valid, errorMessage: valid ? undefined : 'Die Recherche ist ungueltig und wird nicht fuer die Empfehlung verwendet.\n\n' + errors.join('\n') } }];
